mapper.insert:
/* DefaultSchGenMapper.insertDefaultSchDayIfAbsent */
INSERT INTO TB_USER_WORK_PLAN (
      CMPNY_CD
    , SITE_CD
    , USER_CD
    , WORK_YMD
    , WORK_PLAN_CD
    , GEN_SOURCE
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
SELECT
      #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{workYmd}
    , #{schCd}
    , 'DEFAULT_SCH'
    , #{operatorNo}
    , NOW()
    , #{operatorNo}
    , NOW()
  FROM DUAL
 WHERE NOT EXISTS (
        SELECT 1
          FROM TB_USER_WORK_PLAN WP
         WHERE WP.CMPNY_CD = #{cmpnyCd}
           AND WP.SITE_CD  = #{siteCd}
           AND WP.USER_CD  = #{userCd}
           AND WP.WORK_YMD = #{workYmd}
       )

mapper.update:
/* DefaultSchGenMapper.updateFutureDefaultSch */
UPDATE TB_USER_WORK_PLAN
   SET WORK_PLAN_CD = #{newSchCd}
     , UPDATE_NO    = #{operatorNo}
     , UPDATE_DATE  = NOW()
 WHERE CMPNY_CD   = #{cmpnyCd}
   AND SITE_CD    = #{siteCd}
   AND USER_CD    = #{userCd}
   AND WORK_YMD   > #{fromYmd}
   AND GEN_SOURCE = 'DEFAULT_SCH'

mapper.select:
/* DefaultSchGenMapper.countActiveSchOnSite */
SELECT COUNT(*)
  FROM TB_SCH_MGMT M
 WHERE M.CMPNY_CD = #{cmpnyCd}
   AND M.SITE_CD  = #{siteCd}
   AND M.SCH_CD   = #{schCd}
   AND M.USE_YN   = 'Y'

/* DefaultSchGenMapper.selectUserSiteCd */
SELECT U.SITE_CD
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USER_CD  = #{userCd}
 LIMIT 1

