/* DefaultSchGenMapper.updateUserDefaultSch */
UPDATE TB_USER
   SET DEFAULT_SCH_CD       = #{defaultSchCd}
     , DEFAULT_SCH_SET_DATE = NOW()
     , UPDATE_NO            = #{operatorNo}
     , UPDATE_DATE          = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}
